<div class="modal fade" id="departmentModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" id="departmentForm"><div class="modal-header"><h5 class="modal-title">Подразделение</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" id="department_id"><div class="mb-3"><label class="form-label">Название</label><input name="name" class="form-control" required></div><div class="mb-3"><label class="form-label">Краткое название</label><input name="short_name" class="form-control"></div><div class="mb-3"><label class="form-label">Тип</label><select name="type" class="form-select" required><option value="department">Отделение</option><option value="administration">Администрация</option><option value="service">Служба</option><option value="office">Кабинет</option><option value="other">Другое</option></select></div><div class="mb-3"><label class="form-label">Родитель</label><select name="parent_id" id="parent_id" class="form-select"><option value="">— верхний уровень —</option></select></div><div class="mb-3"><label class="form-label">Порядок</label><input type="number" min="0" name="sort_order" class="form-control" value="0"></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="department_active" checked><label class="form-check-label">Активно</label></div><div id="depError" class="alert alert-danger mt-3 d-none"></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Отмена</button><button class="btn btn-primary">Сохранить</button></div></form></div></div>
