@push('scripts')
<script>
let deps=[];function e(v){return $('<div>').text(v??'').html()}function depName(id){return deps.find(x=>x.id==id)?.name||'—'}function typeName(v){return {administration:'Администрация',department:'Отделение',service:'Служба',office:'Кабинет',other:'Другое'}[v]||v}
function loadDeps(){$.get('{{ route('departments.index') }}',r=>{deps=r;let h='';r.forEach(d=>h+=`<tr><td><strong>${e(d.name)}</strong></td><td>${e(d.short_name||'')}</td><td>${e(typeName(d.type))}</td><td>${e(depName(d.parent_id))}</td><td>${d.users_count}</td><td>${d.is_active?'<span class="badge text-bg-success">Активно</span>':'<span class="badge text-bg-secondary">Отключено</span>'}</td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="{{ url('/departments') }}/${d.id}/360" title="360°"><i class="bi bi-speedometer2"></i></a> @if(auth()->user()->isManager())<button class="btn btn-sm btn-outline-primary" onclick="editDepartment(${d.id})"><i class="bi bi-pencil"></i></button>@endif</td></tr>`);$('#departmentRows').html(h||'<tr><td colspan="7" class="text-center py-4 text-muted">Нет подразделений</td></tr>');let o='<option value="">— верхний уровень —</option>';r.forEach(d=>o+=`<option value="${d.id}">${e(d.name)}</option>`);$('#parent_id').html(o)})}
function newDepartment(){$('#departmentForm')[0].reset();$('#department_id').val('');$('#department_active').prop('checked',true);$('#depError').addClass('d-none')}
function editDepartment(id){let d=deps.find(x=>x.id==id);newDepartment();$('#department_id').val(id);for(let k of ['name','short_name','type','parent_id','sort_order'])$(`[name=${k}]`).val(d[k]??'');$('#department_active').prop('checked',!!d.is_active);bootstrap.Modal.getOrCreateInstance(document.getElementById('departmentModal')).show()}
$('#departmentForm').on('submit',function(x){x.preventDefault();let id=$('#department_id').val(),data=Object.fromEntries(new FormData(this).entries());data.is_active=$('#department_active').is(':checked')?1:0;$.ajax({url:id?'{{ url('/ajax/departments') }}/'+id:'{{ route('departments.store') }}',method:id?'PATCH':'POST',data}).done(()=>{bootstrap.Modal.getInstance(document.getElementById('departmentModal')).hide();loadDeps()}).fail(r=>$('#depError').removeClass('d-none').text(r.responseJSON?.message||'Ошибка сохранения'))});loadDeps();
</script>
@endpush
